9. 
10. function returnsStringForAllTestValues(testFn) {
11.   describe(`tiny-rep-serializer function "${
12.     testFn.name
13.   }" returns a string for all test values`, () => {
14.     Object.keys(allCases).forEach(testCase => {
15.       it(`${testFn.name} should return a string; case: ${testCase}`, () =>
16.         expect(typeof testFn(allCases[testCase])).toBe("string"));
17.     });
18.   });
19. }
20. 
21. returnsStringForAllTestValues(getClass);
22. returnsStringForAllTestValues(getType);
23. 
24. describe("tinyRepStringify always returns an array with a short string and a bool", () => {
25.   Object.keys(allCases).forEach(testCase => {
26.     it(`tinyRepStringify(...)[0] should be a string; case: ${testCase}`, () =>
27.       expect(typeof tinyRepStringify(allCases[testCase])[0]).toBe("string"));
28. 
