30.       expect(
31.         tinyRepStringify(allCases[testCase])[0].length <= MAX_TINY_STRING_LEN
32.       ).toBe(true));
33. 
34.     it(`tinyRepStringify(...)[1] should be a boolean chars; case: ${testCase}`, () =>
35.       expect(typeof tinyRepStringify(allCases[testCase])[1]).toBe("boolean"));
36.   });
37. });
38. 
39. describe("objSize(x) returns a number if x not nulland not undefined", () => {
40.   Object.keys(allCases).forEach(testCase => {
41.     const testValue = allCases[testCase];
