43.       it(`objSize should be undefined; case: ${testCase}`, () =>
44.         expect(objSize(testValue)).toBeUndefined());
45.     } else {
46.       it(`objSize should be a number; case: ${testCase}`, () =>
47.         expect(typeof objSize(testValue)).toBe("number"));
48.     }
49.   });
50. });
